var projectLabel=function(){return app.workspace&&app.workspace.current_project?app.workspace.current_project:"Choose a project";};var renderShell=function(){$("#projectPath").textContent=projectLabel();$("#newBtn").style.display=app.route==="sessions"?"inline-block":"none";var titles={overview:"Overview",sessions:"Sessions",team:"Team",tasks:"Tasks",nodes:"Nodes",activity:"Activity",settings:"Settings",context:"Project context",approvals:"Host approvals","team-templates":"Team templates","settings-integrations":"Integrations","settings-diagnostics":"Diagnostics"};$("#pageTitle").textContent=titles[app.route]||"Overview";document.querySelectorAll("[data-nav]").forEach(function(el){el.classList.toggle("active",el.getAttribute("data-nav")==app.route);});};
