var statePill=function(state){var s=String(state||"").toLowerCase();var cls={"running":"running","idle":"idle","starting":"starting","stale":"stale","stopped":"stopped","failed":"failed","offline":"offline","working":"working"}[s]||"";return '<span class="pill '+cls+'">'+esc(String(state||"Unknown"))+'</span>';};
